import {TEMPLATES,VISUALS,allActivities,availableActivities} from './teaching.js';

const studioEscape=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const studioVisualSelect=(id,value)=>`<label class="compact-field">Imagem ou símbolo<select id="${id}"><option value="">Somente texto</option>${VISUALS.map(v=>`<option value="${studioEscape(v)}" ${v===value?'selected':''}>${v}</option>`).join('')}</select></label>`;

export function activityManagerHTML(state,icon){
 const available=availableActivities(state),all=allActivities(state),own=state.customActivities||[];
 return `<section class="panel teacher-manager"><div class="panel-heading"><div><div class="eyebrow">PLANEJE A PRÓXIMA DESCOBERTA</div><h3>Atividades disponíveis para brincar</h3><p>Escolha o que aparece na aventura e na biblioteca deste aparelho.</p></div><span class="badge">${available.length} disponíveis</span></div><form id="availability-form"><div class="availability-grid">${all.map(a=>`<label class="activity-toggle"><input type="checkbox" name="available" value="${studioEscape(a.id)}" ${state.enabledActivityIds.includes(a.id)?'checked':''}><span class="icon-circle ${a.color}">${icon(a.icon)}</span><span><strong>${studioEscape(a.name)}</strong><small>${studioEscape(a.skill)}${a.template?' · da professora':''}</small></span></label>`).join('')}</div><div class="manager-footer"><p>A seleção vale para os perfis de teste deste navegador.</p><button class="primary" type="submit">${icon('check')}Salvar seleção</button></div><div id="availability-error" class="form-error" role="alert"></div></form></section><section class="panel teacher-manager"><div class="panel-heading"><div><h3>Atividades da professora</h3><p>Crie a partir de um modelo, experimente e disponibilize para os testes.</p></div><button class="primary" data-action="create-activity">${icon('plus')}Criar atividade</button></div>${own.length?`<div class="teacher-activity-list">${own.map(a=>`<article class="teacher-activity-row"><div class="icon-circle ${a.color}">${icon(a.icon)}</div><div class="teacher-activity-description"><strong>${studioEscape(a.name)}</strong><small>${a.questions.length} desafios · ${a.age==='mixed'?'Idade flexível':a.age+' anos'} · ${a.published?'Disponibilizada':'Rascunho'}</small></div><div class="button-row"><button class="secondary" data-action="preview-teacher" data-id="${studioEscape(a.id)}">Testar</button><button class="quiet" data-action="edit-activity" data-id="${studioEscape(a.id)}">Editar${icon('arrow')}</button></div></article>`).join('')}</div>`:`<div class="template-grid">${TEMPLATES.map(t=>`<button class="template-card ${t.color}" data-action="create-activity" data-template="${t.id}">${icon(t.icon)}<strong>${t.name}</strong><span>${t.description}</span></button>`).join('')}</div>`}<div class="pack-toolbar"><div><strong>Leve as atividades para outro aparelho</strong><p>Exporte um pacote e importe na Lumi do aparelho de teste. O pacote não inclui perfis nem registros de crianças.</p></div><div class="button-row"><button class="secondary" data-action="export-activities">${icon('download')}Exportar atividades</button><button class="secondary" data-action="import-activities">${icon('plus')}Importar pacote</button></div><input id="teacher-pack-file" type="file" accept=".json,application/json" hidden></div></section>`;
}

export function editorHTML(draft,icon){
 if(!draft)return `<section class="panel"><div class="eyebrow">UMA IDEIA, MUITAS DESCOBERTAS</div><h1>Que atividade vamos preparar?</h1><p class="editor-intro">Escolha um modelo. A Lumi cuida da interação; você define o conteúdo e o objetivo.</p><div class="template-grid">${TEMPLATES.map(t=>`<button class="template-card ${t.color}" data-action="choose-template" data-template="${t.id}">${icon(t.icon)}<strong>${t.name}</strong><span>${t.description}</span></button>`).join('')}</div><button class="quiet" data-action="editor-back">${icon('back')}Voltar à escola</button></section>`;
 const template=TEMPLATES.find(t=>t.id===draft.template);
 return `<div class="page-heading adult-heading"><div><div class="eyebrow">ESPAÇO DA PROFESSORA</div><h1>${draft.name?'Preparar a atividade':'Uma atividade com seu olhar.'}</h1><p>${template.name} · ${template.description}</p></div><button class="secondary" data-action="editor-back">${icon('back')}Voltar à escola</button></div><form id="teacher-editor-form" class="teacher-editor"><section class="panel editor-metadata"><div class="form-field"><label for="teacher-title">Nome da atividade</label><input id="teacher-title" maxlength="70" placeholder="Ex.: Os bichinhos do jardim" value="${studioEscape(draft.name)}" required></div><div class="editor-two-columns"><div class="form-field"><label for="teacher-skill">O que vamos explorar?</label><input id="teacher-skill" maxlength="100" placeholder="Ex.: Sons no começo das palavras" value="${studioEscape(draft.skill)}" required></div><div class="form-field"><label for="teacher-age">Faixa etária sugerida</label><select id="teacher-age">${[['mixed','Ajustável à turma'],['3','3 anos'],['4','4 anos'],['5','5 anos']].map(([value,label])=>`<option value="${value}" ${draft.age===value?'selected':''}>${label}</option>`).join('')}</select></div></div><div class="form-field"><label for="teacher-description">Convite para a atividade</label><input id="teacher-description" maxlength="200" placeholder="Ex.: Vamos encontrar os amigos da Lumi!" value="${studioEscape(draft.description)}"></div></section><div class="section-heading"><div><h2>Seus desafios</h2><p>Inclua de 1 a 12. A ordem abaixo será a ordem do jogo.</p></div></div>${draft.questions.map((q,index)=>questionEditorHTML(q,index,draft.template,icon)).join('')}<button class="secondary" data-action="add-question" type="button" ${draft.questions.length>=12?'disabled':''}>${icon('plus')}Adicionar desafio</button><div class="editor-action-bar"><div><strong>Confira o conteúdo antes de disponibilizar.</strong><p>Novas falas usam a voz do aparelho enquanto não houver gravação correspondente.</p><div id="editor-error" class="form-error" role="alert" tabindex="-1"></div></div><div class="button-row"><button class="secondary" type="button" data-action="test-editor">Testar sem registrar</button><button class="secondary" type="button" data-action="save-teacher">${icon('check')}${draft.published?'Salvar alterações':'Salvar rascunho'}</button><button class="primary" type="submit">Disponibilizar na prévia${icon('arrow')}</button></div></div></form>`;
}

function questionEditorHTML(q,index,template,icon){
 const key='question-'+index;
 let content='';
 if(template==='build'){
  const extra=[...q.options];for(const piece of q.correct){const i=extra.indexOf(piece);if(i>=0)extra.splice(i,1);}
  content=`<div class="editor-two-columns"><div class="form-field"><label for="${key}-target">Palavra</label><input id="${key}-target" maxlength="30" value="${studioEscape(q.target)}" placeholder="BOLA"></div><div class="form-field"><label for="${key}-pieces">Sílabas na ordem da palavra</label><input id="${key}-pieces" value="${studioEscape(q.correct.join(', '))}" placeholder="BO, LA"><small>Separe com vírgulas. Ex.: BA, NA, NA.</small></div></div><div class="editor-two-columns"><div class="form-field"><label for="${key}-extra">Outras sílabas para escolher</label><input id="${key}-extra" value="${studioEscape(extra.join(', '))}" placeholder="MA, TO"><small>Opcional. Até 8 opções contando as sílabas da palavra.</small></div>${studioVisualSelect(key+'-visual',q.visual)}</div>`;
 }else{
  if(template==='story')content+=`<div class="form-field"><label for="${key}-story">Trecho da história</label><textarea id="${key}-story" rows="4" maxlength="1200" placeholder="Conte o que aconteceu com a Lumi...">${studioEscape(q.text)}</textarea></div>${studioVisualSelect(key+'-visual',q.visual)}`;
  content+=`<div class="editor-options">${q.options.map((option,i)=>`<div class="editor-option"><label class="compact-field">Resposta ${i+1}<input id="${key}-option-${i}" maxlength="40" placeholder="Ex.: GATO" value="${studioEscape(option)}"></label>${studioVisualSelect(key+'-visual-'+i,q.visuals?.[option])}</div>`).join('')}</div><div class="form-field"><label for="${key}-correct">Qual resposta é a correta?</label><select id="${key}-correct"><option value="">Selecione...</option>${q.options.map((option,i)=>`<option value="${i}" ${option&&option===q.correct?'selected':''}>Resposta ${i+1}${option?' · '+studioEscape(option):''}</option>`).join('')}</select></div>`;
 }
 return `<section class="panel question-editor" data-question-editor="${index}" data-option-count="${q.options.length}"><div class="panel-heading"><h3>Desafio ${index+1}</h3><button class="quiet" type="button" data-action="remove-question" data-index="${index}" aria-label="Remover desafio ${index+1}">${icon('close')}Remover</button></div><div class="form-field"><label for="${key}-prompt">${template==='story'?'Pergunta sobre a história':'Instrução para a criança'}</label><input id="${key}-prompt" maxlength="250" placeholder="Ex.: Qual bichinho começa como GATO?" value="${studioEscape(q.prompt)}"></div>${content}</section>`;
}

export function readEditorDraft(document,draft){
 const value=id=>document.querySelector('#'+id)?.value??'';
 const splitParts=raw=>raw.split(/[,;\s]+/).map(s=>s.trim()).filter(Boolean);
 const questions=[...document.querySelectorAll('[data-question-editor]')].map((node,index)=>{
  const key='question-'+index,prompt=value(key+'-prompt');
  if(draft.template==='build'){
   const correct=splitParts(value(key+'-pieces'));
   return {type:'build',prompt,target:value(key+'-target'),correct,options:[...correct,...splitParts(value(key+'-extra'))],visual:value(key+'-visual')};
  }
  const count=Number(node.dataset.optionCount)||3;
  const options=Array.from({length:count},(_,i)=>value(key+'-option-'+i));
  const correctIndex=value(key+'-correct');
  return {type:draft.template,prompt,options,correct:correctIndex===''?'':options[Number(correctIndex)],visuals:Object.fromEntries(options.map((option,i)=>[option,value(key+'-visual-'+i)])),...(draft.template==='story'?{text:value(key+'-story'),visual:value(key+'-visual')}:{})};
 });
 return {...draft,name:value('teacher-title'),skill:value('teacher-skill'),age:value('teacher-age'),description:value('teacher-description'),questions};
}
